static int hex_byte(const char *p)
{
   int nib1, nib2;

   nib1 = hex_digit(p[0]);
   if (nib1 < 0)
      return -1;
   nib2 = hex_digit(p[1]);
   if (nib2 < 0)
      return -1;
   return (nib1 << 4) | nib2;
}

